<template>
  <div class="optimization">
    <OptimizationHeader :title="title" :name="name" :status="status" />
    <OptimizationOption :information="headerData" @checkError="checkError" @generateCard="generate"
      @testCard="testing" />
    <div class="optimization-table__box">
      <CustomTable :ItemRows="itemRow" :headerRows="headerRow" @slot-clicked="handleButtonClick"
        :current-page="pagination.currentPage" :per-page="pagination.perPage" :total="pagination.totalPages"
        @update:currentPage="(val) => handlePageChange(val)">
        <template #slot-end="{ item, emitEvent }">
          <div class="table-box__slot-box">
            <ButtonUI svg="card-generation" :buttonClass="'btn--third'" @click="emitEvent('generation', item)" />
            <ButtonUI svg="pencil-svg" :buttonClass="'btn--third'" @click="emitEvent('redact', item)" />
            <ButtonUI svg="search-svg" :buttonClass="'btn--third'" @click="emitEvent('serch', item)" />
          </div>
        </template>
      </CustomTable>
    </div>

    <PopupCodeEditor v-if="isOPenCode" v-model="xmlText" @closing="isOPenCode = false" />
    <CustomPopUP v-if="isOpen" name="Error" :data="errorList" @closing="isOpen = false" />
    <CustomPopUP v-if="isOpenItemError" name="Error" :data="itemErrorList" @closing="isOpenItemError = false" />
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue';

import { useSiteMap } from '@/store/Table/siteMap.js';
//
import { useQueryParams } from '@/composables/useQueryParams';
import {
  generateSitemaps,
  getStatisticAllFiles,
  testingSitemaps,
} from '@/services/apiClient.js';

import CustomTable from '@/components/UI/CustomTable';
import ButtonUI from '@/components/UI/ButtonUI';

import CustomPopUP from '@/components/POPUP/PopUp';
import OptimizationHeader from '@/components/SEO/OptimizationHeader';
import OptimizationOption from '@/components/SEO/OptimizationOption';
import PopupCodeEditor from '@/components/SEO/EditoPopUpMirrorCode';


const title = ref('Карта разделов');
const name = ref('Иван Иванов');
const status = ref('сейчас на странице');
const pagination = ref({ currentPage: 0, perPage: 0, totalPages: 0 });

const itemRow = ref([]);
const headerRow = ref([]);
const isOPenCode = ref(false);

// const code = ref({
//   text: '<note><to>User</to><message>Hello XML!</message></note>',
//   language: 'xml',
// });
const xmlText = ref('<note><to>User</to><message>Hello XML!</message></note>');
const siteMapStore = useSiteMap();

const isOpen = ref(false);

const headerData = ref(null);
const errorList = ref([]);

const isOpenItemError = ref(false);
const itemErrorList = ref([]);

/* eslint-disable no-unused-vars */

const { queryParams, updateQueryParams, loadQueryParamsFromRoute } =
  useQueryParams();
// нужен ли этот лог в проекте
console.log(queryParams, 'собранные параметры');

/* eslint-enable no-unused-vars */

const getFilters = async () => {
  const data = await getStatisticAllFiles();
  // можно переписать с env брать путь
  errorList.value = data.errors_report.map((item) => ({
    ...item,
    path: item.path.startsWith('http')
      ? item.path
      : `https://aligo.ru/${item.path}`,
  }));

  headerData.value = data;
};
const testing = async () => {
  const data = await testingSitemaps();
  errorList.value = data.errors_report.map((item) => ({
    ...item,
    path: item.path.startsWith('http')
      ? item.path
      : `https://aligo.ru/${item.path}`,
  }));
};
const handlePageChange = (newPage) => {
  pagination.value.currentPage = newPage;
  // getTableItem();
  updateQueryParams();
};
const generate = async () => {
  const data = await generateSitemaps();
  // при генерации карточек если
  if (data) {
    console.log(data);
  }
};
const getItemRow = async () => {
  await siteMapStore.getSitemaps();
  itemRow.value = siteMapStore.getItemRow;
};
const getHeaderRow = () => {
  headerRow.value = siteMapStore.getHeaderRow;
  // const result = generateSitemaps();
  // if (result) {
  //   console.log(result);
  // }
};
const checkError = () => {
  isOpen.value = true;
};
const handleButtonClick = (name, item) => {
  console.log(name, item);
  if (name === 'redact') {
    isOPenCode.value = true;
  }
};

onMounted(() => {
  getItemRow();
  getHeaderRow();
  getFilters();
  loadQueryParamsFromRoute();
});
</script>

