<template>
  <div class="popup__content">
    <ClosureSvg class="popup__svg-closure" @click="$emit('closing')" />

    <Codemirror
      v-model="code"
      placeholder="XML-код здесь..."
      :style="{ height: '400px', width: '100%' }"
      :autofocus="true"
      :indent-with-tab="true"
      :tab-size="2"
      :extensions="extensions"
      @ready="handleReady"
      @change="log('change', $event)"
      @focus="log('focus', $event)"
      @blur="log('blur', $event)"
    />
  </div>
</template>

<script>
import { defineComponent, ref, shallowRef } from 'vue';
import { Codemirror } from 'vue-codemirror';
import { xml } from '@codemirror/lang-xml';
import { oneDark } from '@codemirror/theme-one-dark';

import ClosureSvg from '@/assets/icons/close-gray';

export default defineComponent({
  name: 'PopupCodeEditor',
  components: {
    Codemirror,
    ClosureSvg,
  },
  emits: ['update:modelValue', 'closing'],
  props: {
    modelValue: {
      type: String,
      required: true,
    },
  },
  setup(props, { emit }) {
    const code = ref(props.modelValue);

    // обновляем родителя при любом изменении
    const updateValue = (val) => {
      emit('update:modelValue', val);
    };

    const extensions = [xml(), oneDark];

    const view = shallowRef(null);
    const handleReady = (payload) => {
      view.value = payload.view;
    };

    const log = (type, e) => {
      console.log(`[${type}]`, e);
      if (type === 'change') updateValue(code.value);
    };

    return {
      code,
      extensions,
      handleReady,
      log,
    };
  },
});
</script>
