import { defineStore } from 'pinia';
import { getSitemaps } from '@/services/apiClient.js';

export const useSiteMap = defineStore('UseSiteMapStore', {
  state: () => ({
    data: null,
    itemRow: [],
    headerRows: [
      { name: 'Карта', width: '350px', helper: false },
      { name: 'Вес, Мб', width: '80px', helper: false },
      { name: 'Ссылок, шт', width: '90px', helper: false },
      { name: 'Изменено', width: '1fr', helper: false },
      { name: 'Ошибки', width: '1fr', helper: false },
      { name: '', width: '150px', helper: false },
    ],
    pagination: { currentPage: 0, perPage: 0, totalPages: 0 },
  }),

  actions: {
    async getSitemaps() {
      const data = await getSitemaps();
      this.pagination.currentPage = data.current_page;
      this.pagination.perPage = data.total_count;
      this.pagination.totalPages = data.total_page;
      this.data = data;
      this.itemRow = data?.data.map((item) => ({
        link: {
          value: item.title,
          link: item.path,
          type: 'link',
        },
        date: {
          value: `${item.weight_KB}`,
          type: 'text',
          contenteditable: false,
        },
        time: {
          value: `${item.count_links}`,
          type: 'text',
          contenteditable: false,
        },
        event: {
          value: `${item.updated_at}`, // или created_at
          type: 'text',
          contenteditable: false,
        },
        errors: {
          value: `${item.errors_count}`,
          type: 'action',
          contenteditable: false,
          id: item.id,
        },
        slot: {
          slot: 'end',
          contenteditable: false,
          id: item.id,
        },
      }));
    },
    filterItem(id) {
      const element = this.data.data.filter((el) => {
        return el.id === id;
      });
      return element[0];
    },
    //  siteMapInfoErrorFetch(){
    //  }
  },

  getters: {
    getHeaderRow: (state) => state.headerRows,
    getItemRow: (state) => state.itemRow,
    getPagination: (state) => state.pagination,
  },
});
